# Generated by scripts/theme.py; source after application defaults.
export BAT_THEME=Dotfiles
export DOTFILES_FZF_COLOR='dark,fg:#D7DFD9,bg:#0D1513,fg+:#EEF1EE,bg+:#26352D,hl:#A6CD82,hl+:#A6CD82,pointer:#ACC8B7,marker:#A6CD82,header:#ACC8B7,prompt:#ACC8B7,info:#A3B1A7,border:#6B8575,spinner:#8CC5CC'
case " ${FZF_DEFAULT_OPTS-} " in
    *" --color=$DOTFILES_FZF_COLOR "*) ;;
